/**
 * Sharedaddy Base Styles
 *
 * Contains styles for modules, containers, buttons
 */


/* Master container */


/* Overall Sharedaddy block title */
div.sharedaddy {
	clear: both;
}

div.sharedaddy h3.sd-title {
	margin: 0 0 1em 0;
	display: inline-block;
	line-height: 1.2;
	font-size: 9pt;
	font-weight: 700;
}


/* Sharing services list */
.sd-sharing {
	margin-bottom: 1em;
}

.sd-content ul {
	padding: 0 !important;
	margin: 0 !important;
	list-style: none !important;
}

.sd-content ul li {
	display: inline-block;
	margin: 0 8px 12px 0;
	padding: 0;
}

/* Sharing email errors */


/* Buttons */
.sd-social-icon .sd-content ul li a.sd-button,.sd-content ul li a.sd-button {		/* official Digg button no longer works, needs cleaning */
	text-decoration: none !important;
	display: inline-block;
	font-size: 13px;
	font-family: "Open Sans", sans-serif;
	font-weight: 500;
	border-radius: 4px;
	color: #2c3338 !important;
	background: #fff;
	box-shadow: 0 1px 2px rgba(0, 0, 0, 0.12), 0 0 0 1px rgba(0, 0, 0, 0.12);
	text-shadow: none;
	line-height: 23px;
	padding: 4px 11px 3px 9px;
}

.sd-content ul li a.sd-button > span {		/* official Digg button no longer works, needs cleaning */
	line-height: 23px;
	margin-left: 6px;
}

/* Icon Only */
.sd-social-icon .sd-content ul li a.sd-button > span {
	margin-left: 0;
}

.source-site .sd-social-icon .sd-content ul li[class*="share-"] a.sd-button.share-icon.no-text span:not(.custom-sharing-span) {
	display: none;
}

/* Text Only */

.sd-social-icon .sd-content ul li a.sd-button:hover,.sd-social-icon .sd-content ul li a.sd-button:active,.sd-social-text .sd-content ul li a.sd-button:hover,.sd-social-text .sd-content ul li a.sd-button:active,.sd-social-icon-text .sd-content ul li a.sd-button:hover,.sd-social-icon-text .sd-content ul li a.sd-button:active,.sd-social-official .sd-content > ul > li > a.sd-button:hover,.sd-social-official .sd-content > ul > li > a.sd-button:active,.sd-social-official .sd-content > ul > li .digg_button > a:hover,.sd-social-official .sd-content > ul > li .digg_button > a:active {
	box-shadow: 0 1px 2px rgba(0, 0, 0, 0.22), 0 0 0 1px rgba(0, 0, 0, 0.22);
}

.sd-social-icon .sd-content ul li a.sd-button:active,.sd-social-text .sd-content ul li a.sd-button:active,.sd-social-icon-text .sd-content ul li a.sd-button:active,.sd-social-official .sd-content > ul > li > a.sd-button:active,.sd-social-official .sd-content > ul > li .digg_button > a:active {
	box-shadow: inset 0 1px 0 rgba(0, 0, 0, 0.16);
}

/* All icons */
.sd-content ul li a.sd-button::before {
	display: inline-block;
	-webkit-font-smoothing: antialiased;
	-moz-osx-font-smoothing: grayscale;
	font: 400 18px/1 social-logos;
	vertical-align: top;
	text-align: center;
}

/* text + icon styles should have relative and top position */

/* Make it look great in Chrome and Safari */
@media screen and (-webkit-min-device-pixel-ratio: 0) {

	.sd-content ul li a.sd-button::before {
		position: relative;
		top: 2px;
	}
}

/* Make it look great in Chrome and Safari */
@media screen and (-webkit-min-device-pixel-ratio: 0) {
}

/* Add more pading on touch devices */

/* Text only */

@media screen and (-webkit-min-device-pixel-ratio: 0) {
}

/* Hack to make the share more button look better on Firefox. */
@-moz-document url-prefix() {
}


/* Individual icons */

.sd-social-icon .sd-content ul li.share-twitter a::before {
	content: "\f10e";
}

.sd-social-icon .sd-content ul li.share-facebook a::before {
	content: "\f203";
}

/* Share count */


/* Individual official buttons */


/* Custom icons */


/* Overflow Sharing dialog */


/**
 * Special colorful look for "Icon Only" option
 */

.sd-social-icon .sd-content ul li[class*="share-"] a,.sd-social-icon .sd-content ul li[class*="share-"] a:hover {
	border-radius: 50%;
	border: 0;
	box-shadow: none;
	padding: 7px;
	position: relative;
	top: -2px;
	line-height: 1;
	width: auto;
	height: auto;
	margin-bottom: 0;
	max-width: 32px;
}

.sd-social-icon .sd-content ul li[class*="share-"] a.sd-button > span {
	line-height: 1;
}

.sd-social-icon .sd-content ul li[class*="share-"] a:hover,.sd-social-icon .sd-content ul li[class*="share-"] div.option a:hover {
	border: none;
	opacity: 0.6;
}


.sd-social-icon .sd-content ul li[class*="share-"] a.sd-button::before {
	top: 0;
}

/* Special look colors */
.sd-social-icon .sd-content ul li[class*="share-"] a.sd-button {
	background: #e9e9e9;
	margin-top: 2px;
	text-indent: 0;
}

.sd-social-icon .sd-content ul li[class*="share-"].share-facebook a.sd-button {
	background: #0866ff;
	color: #fff !important;
}

.sd-social-icon .sd-content ul li[class*="share-"].share-twitter a.sd-button {
	background: #000;
	color: #fff !important;
}

@media print {

	.sharedaddy.sd-sharing-enabled {
		display: none;
	}
}

